#!/bin/bash
# Generated by Claude Fable 5 (Anthropic)
# =============================================================================
# overhead_sweep_v4.sh — Isaac ROS overhead campaign on the -wip images.
#
# Per benchmark (image fish-r2b-<bench>-wip:latest, TRT cache persistent):
#   warmup x1              — FISH off, TRT compile, results discarded
#   base   xN              — FISH off                (baseline)
#   lttng  xN              — FISH on, FISH_NSYS_DISABLE=1 (LTTng only)
#   nsys   xN              — FISH on + CUPTI + nsys  (full FISH)
# N = $REPS (default 3).
#
# Each run captures, under $DEST_BASE/<bench>/<mode>_<i>/ :
#   r2b-log-*.json   — ros2_benchmark's OWN final report (the primary metric)
#   launch.log       — full launch_test output (report parse fallback)
#   cpu.log          — container CPU jiffies sampler (2 s), as in the Autoware pair
#   fish session dir — lttng/nsys modes only (trace health: events, discards)
# Summary: scripts/overhead_sweep_report.py builds the table from these.
#
# Differences vs overnight_sweep_v3.sh: -wip images (current tracepoint overlay
# baked), install_fish.sh per run (wrapper+python only, overlay already baked),
# three measured modes, benchmark report + cpu probe capture.
# usage: overhead_sweep_v4.sh [bench ...]      (default: the 17 verified)
# =============================================================================
set -uo pipefail
REPO_ROOT="$(cd "$(dirname "$0")/.." && pwd)"
SMOKE_TIMEOUT=${SMOKE_TIMEOUT:-900}
FISH_NSYS_DRAIN=${FISH_NSYS_DRAIN:-60}
DEST_BASE=${DEST_BASE:-$HOME/fish_traces/overhead_isaac}
TRT_CACHE_HOST=${TRT_CACHE_HOST:-/home/tue037807/trt_cache_v3}
NGC_ASSETS=${NGC_ASSETS:-/home/tue037807/isaac_ros_assets}
R2B_DATASET=${R2B_DATASET:-/home/tue037807/r2bdataset2023_v3}
R2B_DATASET_2024=${R2B_DATASET_2024:-/home/tue037807/r2bdataset2024_v1}
REPS=${REPS:-3}
mkdir -p "$DEST_BASE" "$TRT_CACHE_HOST"
log() { echo "[v4 $(date +%H:%M:%S)] $*" >&2; }

declare -A SCRIPT_OF=(
    [apriltag]="isaac_ros_apriltag_node"
    [dnn_image_encoder]="isaac_ros_dnn_image_encoder_node"
    [image_proc]="isaac_ros_rectify_node"
    [stereo_image_proc]="isaac_ros_disparity_node"
    [nvblox]="isaac_ros_nvblox_node"
    [visual_slam]="isaac_ros_visual_slam_node"
    [nitros_bridge]="isaac_ros_nitros_bridge"
    [detectnet]="isaac_ros_detectnet_graph"
    [ess]="isaac_ros_ess_node"
    [segformer]="isaac_ros_segformer_graph"
    [unet]="isaac_ros_unet_graph"
    [tensor_rt]="isaac_ros_tensor_rt_ps_node"
    [triton]="isaac_ros_triton_ps_node"
    [bi3d]="isaac_ros_bi3d_node"
    [bi3d_freespace]="isaac_ros_bi3d_fs_node"
    [rtdetr]="isaac_ros_rtdetr_graph"
    [dope]="isaac_ros_dope_graph"
)

_MANUAL=/host/isaac_assets/manual_models
_BM=/root/ros_ws/src/ros2_benchmark/assets/models
declare -A MODEL_WIRE
MODEL_WIRE[detectnet]="mkdir -p $_BM/peoplenet && cp $_MANUAL/peoplenet/* $_BM/peoplenet/"
MODEL_WIRE[ess]="mkdir -p $_BM/ess/plugins/x86_64 && cp $_MANUAL/ess/*.onnx $_BM/ess/ && cp $_MANUAL/ess/plugins/x86_64/ess_plugins.so $_BM/ess/plugins/x86_64/"
MODEL_WIRE[unet]="mkdir -p $_BM/peoplesemsegnet_shuffleseg && cp $_MANUAL/peoplesemsegnet_shuffleseg/peoplesemsegnet_shuffleseg.onnx $_BM/peoplesemsegnet_shuffleseg/"
MODEL_WIRE[tensor_rt]=${MODEL_WIRE[unet]}
MODEL_WIRE[triton]="${MODEL_WIRE[unet]} && cp $_MANUAL/peoplesemsegnet_shuffleseg/config.pbtxt $_BM/peoplesemsegnet_shuffleseg/"
MODEL_WIRE[segformer]="mkdir -p $_BM/peoplesemsegformer && cp $_MANUAL/peoplesemsegformer/peoplesemsegformer.onnx $_BM/peoplesemsegformer/"
MODEL_WIRE[bi3d]="mkdir -p $_BM/bi3d && cp $_MANUAL/bi3d/*.onnx $_BM/bi3d/"
MODEL_WIRE[bi3d_freespace]=${MODEL_WIRE[bi3d]}
MODEL_WIRE[rtdetr]="mkdir -p $_BM/sdetr && cp $_MANUAL/sdetr/sdetr_grasp.onnx $_BM/sdetr/"
MODEL_WIRE[dope]="mkdir -p $_BM/ketchup && cp $_MANUAL/ketchup/ketchup.onnx $_BM/ketchup/"
BENCHES=(${@:-apriltag dnn_image_encoder image_proc stereo_image_proc nvblox \
  visual_slam nitros_bridge detectnet ess segformer unet tensor_rt triton \
  bi3d bi3d_freespace rtdetr dope})

run_one() {   # $1=bench $2=mode(warmup|base|lttng|nsys) $3=rep-index
    local B=$1 MODE=$2 IDX=$3
    local IMG=${IMG_OVERRIDE:-fish-r2b-$B-wip:latest}
    local SCRIPT_STEM="${SCRIPT_OF[$B]}"
    local MODEL_CMD="${MODEL_WIRE[$B]:-:}"
    local OUT="$DEST_BASE/$B/${MODE}_${IDX}"
    mkdir -p "$OUT"
    local FISH_ON=0 EXTRA_ENV=()
    case $MODE in
        lttng) FISH_ON=1; EXTRA_ENV=(-e FISH_NSYS_DISABLE=1) ;;
        nsys)  FISH_ON=1
               # CUDA_EVT=0 → minimal nsys flags (no --cuda-event-trace);
               # smoke 2026-08-30: with the flag the NITROS pipeline delivered
               # ZERO messages to the monitor (test failed after 220 s).
               [ "${CUDA_EVT:-1}" = 1 ] && EXTRA_ENV=(-e FISH_CUDA_EVENT_TRACE=1) ;;
    esac
    log "----- $B [$MODE #$IDX] FISH=$FISH_ON -----"
    timeout "$SMOKE_TIMEOUT" docker run --rm --gpus all --privileged --net host \
        --shm-size=2g \
        -v "$REPO_ROOT":/host/fish_src:ro \
        -v "$NGC_ASSETS":/host/isaac_assets:ro \
        -v "$R2B_DATASET":/host/r2bdataset:ro \
        -v "$R2B_DATASET_2024":/host/r2bdataset_2024:ro \
        -v "$NGC_ASSETS/apt_cache":/host/apt_cache:ro \
        -v "$OUT":/root/fish_traces \
        -v "$TRT_CACHE_HOST":/root/.cache \
        -e ISAAC_ROS_ACCEPT_EULA=1 -e ISAAC_ROS_WS=/root/ros_ws \
        -e FISH_ENABLED=$FISH_ON -e FISH_NSYS_DRAIN=$FISH_NSYS_DRAIN \
        "${EXTRA_ENV[@]}" \
        "$IMG" bash -lc "
            set -e
            export PYTHONUNBUFFERED=1
            # cpu probe (identical in every mode)
            ( set +e; while :; do
                printf '%s ' \$(date +%s.%N)
                awk '{ i=index(\$0,\")\"); split(substr(\$0,i+2),a,\" \"); s+=a[12]+a[13]; c++ }
                     END{ printf \"%d %d\n\", s, c }' /proc/[0-9]*/stat 2>/dev/null || echo NA NA
                sleep 2
              done > /root/fish_traces/cpu.log 2>/dev/null ) &

            # trtexec / dcgm runtime deps (as in v3; wip images may lack them)
            if [ ! -x /usr/src/tensorrt/bin/trtexec ]; then
                NVINFER_VER=\$(dpkg-query -W -f='\${Version}' libnvinfer-dev 2>/dev/null || true)
                if [ -n \"\$NVINFER_VER\" ]; then
                    apt-get update >/tmp/apt_update.log 2>&1 || true
                    apt-get install -y \"libnvinfer-bin=\$NVINFER_VER\" >/tmp/trtexec.log 2>&1 || true
                fi
            fi
            if [ ! -f /usr/lib/x86_64-linux-gnu/libdcgm.so.3 ] && [ -f /host/apt_cache/datacenter-gpu-manager_3.3.9_amd64.deb ]; then
                dpkg -i /host/apt_cache/datacenter-gpu-manager_3.3.9_amd64.deb >/tmp/dcgm.log 2>&1 || true
            fi

            source /opt/ros/humble/setup.bash
            source /root/trace_overlay_ws/install/setup.bash
            if [ \"$FISH_ON\" = 1 ]; then
                rm -rf /root/fish_interfere
                cp -rT /host/fish_src /root/fish_interfere
                cd /root/fish_interfere
                FISH_SETUP_PARENT=1 source scripts/install_fish.sh >/tmp/fish_install.log 2>&1
                export PATH=/opt/ros/humble/fish/bin:\$PATH
                export PYTHONPATH=/opt/ros/humble/fish/python:\$PYTHONPATH
                # NO replay/auto_stop: v3's 'sleep 60' auto-stop SIGINTs the
                # nsys-wrapped container mid-benchmark (smoke 2026-08-30:
                # 'Processes under test stopped before tests completed', no
                # r2b report). The benchmark must run to completion; the
                # last-node-exit path stops the trace + drains nsys instead.
                sed -i 's|^replay_rosbag = .*|replay_rosbag = false|' /opt/ros/humble/fish/fish_settings.ini
            fi
            mkdir -p /workspaces; ln -sfn /root/ros_ws /workspaces/isaac_ros-dev
            DEST_DS=/root/ros_ws/src/ros2_benchmark/assets/datasets/r2b_dataset
            mkdir -p \$DEST_DS
            for bag in /host/r2bdataset/* /host/r2bdataset_2024/*; do
                [ -d \"\$bag\" ] && ln -sf \"\$bag\" \"\$DEST_DS/\$(basename \"\$bag\")\" 2>/dev/null
            done
            ${MODEL_CMD}
            SCRIPT=\$(find /root/ros_ws/src/isaac_ros_benchmark -name '${SCRIPT_STEM}.py' -type f | head -1)
            [ -z \"\$SCRIPT\" ] && { echo '[v4] script not found'; exit 91; }
            rm -f /tmp/r2b-log-*
            date +%s.%N > /root/fish_traces/t_start.txt
            set +e
            launch_test \"\$SCRIPT\"
            rc=\$?
            date +%s.%N > /root/fish_traces/t_end.txt
            cp /tmp/r2b-log-* /root/fish_traces/ 2>/dev/null
            echo \"[v4] launch_test rc=\$rc, reports: \$(ls /tmp/r2b-log-* 2>/dev/null | wc -l)\"
            exit \$rc
        " > "$OUT/launch.log" 2>&1
    local rc=$?
    local nrep; nrep=$(ls "$OUT"/r2b-log-*.json 2>/dev/null | wc -l)
    log "$B [$MODE #$IDX] rc=$rc report_json=$nrep"
    echo "$B,$MODE,$IDX,$rc,$nrep,$(date +%s)" >> "$DEST_BASE/runs.csv"
    return $rc
}

[ -f "$DEST_BASE/runs.csv" ] || echo "bench,mode,rep,rc,report_json,epoch" > "$DEST_BASE/runs.csv"
for B in "${BENCHES[@]}"; do
    docker image inspect fish-r2b-$B-wip:latest >/dev/null 2>&1 || { log "$B: no -wip image, SKIP"; continue; }
    if [ "${SKIP_WARMUP:-0}" != 1 ]; then
        run_one "$B" warmup 1 || log "$B warmup failed (continuing)"
        sleep 5
    fi
    for M in ${MODES:-base lttng nsys}; do
        for i in $(seq 1 $REPS); do run_one "$B" "$M" "$i"; sleep 5; done
    done
done
log "sweep complete → $DEST_BASE/runs.csv"
